"——与主画幅不同画幅的平台(如主画幅选 16:9 时的 TikTok/抖音)在发布期由 platform-adapter 从母版裁切适配,不重新生成视频;语言约束剧本/台词/旁白/字幕/配音/发布物料(给生成模型的英文 prompt 不受影响);草稿分辨率用于迭代/待审版本,成片分辨率是审核确认后终稿的目标分辨率——与草稿档不同时默认由超分(upscale)得到,不重新生成;分辨率越高视频生成费用越高(4K 仅 Seedance 2.0 标准版支持)。": "— платформы с форматом, отличным от основного (например, TikTok/Douyin при основном 16:9), на этапе публикации адаптируются platform-adapter кадрированием из мастер-версии, видео не генерируется заново; язык определяет сценарий/диалоги/наррацию/субтитры/озвучку/материалы публикации (английские prompt для генеративных моделей не затрагиваются); черновое разрешение используется для итераций/версий на проверку, разрешение финальной версии — целевое разрешение утверждённого финального варианта: при отличии от чернового по умолчанию получается апскейлом (upscale), без повторной генерации; чем выше разрешение, тем дороже генерация видео (4K поддерживает только стандартная версия Seedance 2.0).",
