"诊断数据:本地记录运行事件与经验卡,手动导出诊断包提交给开发者;永不自动上传": "Диагностические данные: локальная запись событий выполнения и карточек опыта, ручной экспорт диагностического пакета для отправки разработчикам; автоматическая выгрузка не выполняется никогда",
"🩺 诊断数据": "🩺 Диагностические данные",
"本地采集": "Локальный сбор",
"开启时在运行结束与生成结束处按字段白名单记录结构化事件(引擎/Agent/渠道/状态/时长/脱敏后的错误模板),只写入本机 data/.videoagents/telemetry/,不含提示词、项目内容、文件路径与 API Key,永不自动上传。「导出诊断包」生成一个 zip(事件 + 环境摘要 + 下方勾选的经验卡),由你自行提交给开发者(如 GitHub issue 附件),用于改进产品。": "При включении в конце выполнения и генерации записываются структурированные события по белому списку полей (движок/Agent/канал/статус/длительность/обезличенный шаблон ошибки) — только в data/.videoagents/telemetry/ на этой машине, без промптов, содержимого проекта, путей к файлам и API-ключей; автоматическая выгрузка не выполняется никогда. «Экспорт диагностического пакета» создаёт zip (события + сводка окружения + отмеченные ниже карточки опыта), который вы сами передаёте разработчикам (например, вложением в GitHub issue) для улучшения продукта.",
"经验卡": "Карточки опыта",
"任务闭环时沉淀的机制性教训(各项目 runs/<task_id>/lesson.md);默认全部不导出,逐张预览、勾选后才会进入诊断包": "Механизменные уроки, фиксируемые при закрытии задач (runs/<task_id>/lesson.md в каждом проекте); по умолчанию ничего не экспортируется — в пакет попадают только карточки, которые вы просмотрели и отметили",
