"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "После нажатия «Включить» управляйте занесёнными материалами ниже; у каждого изображения на странице предпросмотра персонажей появится кнопка «В библиотеку», а при перегенерации группы занесённые (Active) референсы автоматически отправляются как asset URI (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Внимание: занесение проходит асинхронную модерацию (Processing → Active/Failed); для генерации видео пригодны только материалы в статусе Active. Материалы изолированы по «проектам» Ark — ProjectName ниже должен совпадать с проектом Ark API Key, используемого для генерации видео на странице «Модели генерации» (по умолчанию default).",
