"视频提示词技能:Prompt 工程师写组级视频提示词时必须套用的官方提示词技能。自动=按真正跑视频生成的模型解析(Seedance 2.5→sd25-pe,Seedance 2.0 系列→sd20-prompt-writing,MiniMax H3→h3-prompt-writing);解析不到时可手选或跳过。H3A 分镜签字时会再次确认并冻结": "Навык видеопромпта: официальный навык написания промптов, который инженер промптов обязан применять при написании групповых видеопромптов. Авто = определяется по модели, которая реально выполняет генерацию видео (Seedance 2.5→sd25-pe, семейство Seedance 2.0→sd20-prompt-writing, MiniMax H3→h3-prompt-writing); при отсутствии совпадения выберите вручную или пропустите. Повторно подтверждается и фиксируется при подписании раскадровки H3A",
