"Seedream 5.0 Lite(Fal 托管;文/图生图/多参考图 ≤10,出图 2K–4K)": "Seedream 5.0 Lite (хостинг Fal; текст/изображение в изображение, до 10 референсов, выход 2K–4K)",
"Seedream 4.5(Fal 托管;文/图生图/多图融合,参考图 ≤10)": "Seedream 4.5 (хостинг Fal; текст/изображение в изображение, слияние нескольких изображений, до 10 референсов)",
