"FLUX.2 Max(Fal 托管;旗舰版,文生图/多图编辑)": "FLUX.2 Max (хостинг Fal; флагман, текст в изображение / редактирование по нескольким изображениям)",
"FLUX Kontext Max(Fal 托管;文生图/多参考图编辑)": "FLUX Kontext Max (хостинг Fal; текст в изображение / редактирование по нескольким референсам)",
