"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "Якорные изображения персонажей/сцены/стиля; в каждом раунде они отправляются как референсы вместе с последним кадром предыдущего клипа, чтобы сохранить персонажей. После запуска заморожены, после остановки можно менять.",
