"⚠ H3 Max Turbo 无参考端点,不支持参考图:首轮用第 1 张参考图作首帧,之后每轮用上一段尾帧作首帧;分辨率仅 480p/768p": "⚠ У H3 Max Turbo нет референс-эндпоинта, референсные изображения не принимаются: раунд 1 использует референс №1 как первый кадр, далее — последний кадр предыдущего клипа; разрешение только 480p/768p",
