"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "После включения справа в поле ввода консоли и в окне «Правка» страниц предпросмотра появляется кнопка микрофона: один клик начинает запись, второй завершает; запись распознаётся локальной моделью faster-whisper и вставляется в позицию курсора (до 60 с, аудио не покидает компьютер, API-ключ не нужен). Язык распознавания следует языку интерфейса. Перед первым использованием модель нужно скачать; чем больше модель, тем точнее, но медленнее: для начала хватит small, на Apple Silicon можно medium или large-v3-turbo.",
